package com.mythicrpg.mining.archaeology.relic;
import net.minecraft.entity.LivingEntity; import net.minecraft.item.ItemStack; import net.minecraft.item.ShieldItem; import net.minecraft.item.tooltip.TooltipType; import net.minecraft.server.network.ServerPlayerEntity; import net.minecraft.text.Text; import net.minecraft.util.Formatting; import java.util.List;
public final class ColossalAegisItem extends ShieldItem { public ColossalAegisItem(Settings s){super(s);} @Override public boolean hasGlint(ItemStack s){return true;} @Override public void appendTooltip(ItemStack s,TooltipContext c,List<Text> t,TooltipType type){RelicLevel l=RelicItemData.getLevel(s);t.add(Text.translatable("tooltip.mythicrpg.archaeology_relic.level",l.displayName()).formatted(l.formatting()));t.add(Text.translatable("tooltip.mythicrpg.colossal_aegis.description").formatted(Formatting.GRAY));} @Override public void onStoppedUsing(ItemStack stack,net.minecraft.world.World world,LivingEntity user,int remaining){super.onStoppedUsing(stack,world,user,remaining);if(!world.isClient&&user instanceof ServerPlayerEntity p)ColossalAegisManager.releaseWave(p,stack);} }
